// Node Code (JavaScript) - Run Once for All Items
const staticData = $getWorkflowStaticData('global');

if (staticData.blCounter === undefined) {
  staticData.blCounter = 0;
}

const items = $input.all();

function generateTimestamp() {
  const now = new Date();
  const yy = String(now.getFullYear()).slice(-2);
  const MM = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  const HH = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  return `${yy}${MM}${dd}${HH}${mm}`;
}

// date_facture arrive en "01/11/2026" (jj/mm/aaaa) -> "2026-11-01"
function formatDateFacture(value) {
  if (!value) return "";
  const s = String(value).trim();
  const m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2]}-${m[1]}`;
  const d = new Date(s);
  if (isNaN(d)) return "";
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
}

// Accepte soit l'item webhook (body.donnees), soit des items déjà éclatés
let lignes = [];
let facture_id = null;

for (const item of items) {
  const body = item.json.body ?? item.json;
  if (Array.isArray(body.donnees)) {
    facture_id = facture_id ?? body.facture_id;
    lignes.push(...body.donnees);
  } else {
    lignes.push(body);
  }
}

// Même référence BL pour toutes les lignes du lot
const blRef = `BL-MAGHREBAIL-${generateTimestamp()}`;

// Un item n8n par ligne
return lignes.map(j => ({
  json: {
    CodeFrs: (j.BPSNUM_0 ?? '').toString().trim(),
    BLFrs: blRef,
    DateBC: formatDateFacture(j.ORDDAT_0),
    N_BC: j.POHNUM_0,
    CodeArticle: j.ITMREF_0,
    Quantite: 1,
    N_B_transport: blRef,
    Matricule: 'A',
    Poids: 0.01,
    Marque: j.XMARQ_0,
    observation: "",
    N_Facture: j.numero_facture,
    email_expediteur: "developpeur.ia@jbel-annour.ma",
    facture_id
  }
}));

// Node Code (JavaScript) - Run Once for All Items
const aggItems = $('Aggregate').all(); // nom exact du node Aggregate
const outputItems = [];

// PSHNUM_0 : pris une seule fois sur l'input courant (node précédent ce Code)
const numero_da = $input.first()?.json?.PSHNUM_0 ?? null;

for (const item of aggItems) {
  const dataArray = Array.isArray(item.json.data) ? item.json.data : [];

  for (const row of dataArray) {
    outputItems.push({
      json: {
        ...row,
        PSHNUM_0: row.PSHNUM_0 ?? numero_da
      }
    });
  }
}

return outputItems;
